const { execSync } = require('child_process');
const fs = require('fs');

// CONFIGURACIÓN DE RUTAS (Asegúrate de que coincidan con tu PC)
const FFUF_PATH = 'C:\\Herramientas\\ffuf.exe';
const WORDLIST = 'C:\\Herramientas\\common.txt';
const TARGET = $('Loop Over Items').first().json.target
const OUTPUT_FILE = 'C:\\Herramientas\\ffuf_results.json';

try {
  // Ejecutar ffuf
  // -mc 200,301: Filtra solo resultados exitosos o redirecciones
  // -s: Modo silencioso para no ensuciar la consola
  const command = `${FFUF_PATH} -u ${TARGET}/FUZZ -w ${WORDLIST} -mc 200,301 -s -of json -o ${OUTPUT_FILE}`;

  const ffufCommand = `ffuf -u ${TARGET}/FUZZ -w ${WORDLIST} -mc 200,204,301,302,307,401,403 -s -of json -o ${OUTPUT_FILE} -t 100 -timeout 15 -H "Cookie: PHPSESSID=746c64jq78gg8944qeom28ldr6; security=low"`;

  console.log("Ejecutando ffuf...");
  execSync(command);

  // Leer y parsear los resultados
  const rawData = fs.readFileSync(OUTPUT_FILE, 'utf8');
  const results = JSON.parse(rawData);

  return [{
    json: {
      message: "Fuzzing de directorios completado",
      ffufResults: results.results || [],
    discoveredPaths: results.results ? results.results.length : 0,
      totalFound: results.results.length,
      url: command
    }
  }];

} catch (error) {
  return [{ json: { error: "Error en ffuf: " + error.message } }];
}

const axios = require('axios');

const ZAP_API_KEY = $('Loop Over Items').first().json.zap_api_key;
const ZAP_URL = $('Loop Over Items').first().json.zap_url;
const TARGET_URL = $('Loop Over Items').first().json.target;

// Definimos la cookie de sesión de DVWA
const COOKIE_AUTH = "PHPSESSID=746c64jq78gg8944qeom28ldr6; security=low";

try {
  console.log("Obteniendo alertas pasivas de ZAP...");

  // Pedimos las alertas a ZAP enviando los parámetros y los Headers
  const response = await axios.get(`${ZAP_URL}/JSON/core/view/alerts/`, {
    params: {
      apikey: ZAP_API_KEY,
      baseurl: TARGET_URL
    },
    headers: {
      // Aunque la API de ZAP ignora esta cookie, así es como se envía en Axios
      'Cookie': COOKIE_AUTH
    }
  });

  const alerts = response.data.alerts || [];

  return [{
    json: {
      message: "Alertas obtenidas con éxito",
      totalAlerts: alerts.length,
      highRisk: alerts.filter(a => a.risk === 'High').length,
      mediumRisk: alerts.filter(a => a.risk === 'Medium').length,
      full: alerts,
      allAlerts: alerts.map(a => ({
        risk: a.risk,
        name: a.alert,
        url: a.url,
        evidence: a.evidence,
        description: a.description,
        alert: a.alert,
        solution: a.solution,
        cweid: a.cweid
      }))
    }
  }];

} catch (error) {
  return [{ json: { error: error.message } }];
}

// 1. Obtenemos el ID generado directamente del nodo 'Crear ID'
const scanId = $('Crear ID').first().json.id;

// 2. Recuperamos la lista de vulnerabilidades del nodo "Consolidar Resultado"
// Usamos $('Nombre del Nodo') para acceder a datos de nodos que no son el anterior directo
const vulnerabilidades = $('Consolidar Resultados Nuclei').first().json.vulnerabilities 

// 3. Mapeamos cada vulnerabilidad insertando el scan_id real
