const { exec } = require('child_process');
const util = require('util');
const fs = require('fs');
const process = require('process')

const execPromise = util.promisify(exec);

const NUCLEI_PATH = 'C:\\Herramientas\\nuclei.exe'; 
const TEMPLATES_PATH = 'C:\\Herramientas\\nuclei-templates\\http';
const OUTPUT_FILE = 'C:\\Herramientas\\nuclei_results_final.json';

let target = $('Loop Over Items').first().json.target

// 1. Corrección de Red: Forzamos localhost para que Windows 11 llegue al contenedor
if (target.includes('localhost')) {
   target = target.replace('localhost', '127.0.0.1');
}

// 2. Entorno unificado: Aseguramos que Nuclei encuentre su configuración
const execOptions = {
    timeout: 1200000, // 20 minutos
    maxBuffer: 1024 * 1024 * 50, // 50MB
    env: {
      ...process.env,
      USERPROFILE: 'C:\\Users\\Lauti Ferreria',
      HOME: 'C:\\Users\\Lauti Ferreria',
      APPDATA: 'C:\\Users\\Lauti Ferreria\\AppData\\Roaming',
      LOCALAPPDATA: 'C:\\Users\\Lauti Ferreria\\AppData\\Local'
    }
};

let list_results;

try {
  // Limpiamos resultados viejos
  if (fs.existsSync(OUTPUT_FILE)) { fs.unlinkSync(OUTPUT_FILE); }

  const command = `"${NUCLEI_PATH}" -u "${target} -t "${TEMPLATES_PATH}" -pn -ni -silent -json-export "${OUTPUT_FILE}"`;
  const newCommand = `${NUCLEI_PATH} -u https://scanme.sh -t C:\Herramientas\nuclei-templates\http -severity critical,high,medium -etags slow -c 100 -rl 500`
  const simpleCommand = `"${NUCLEI_PATH}" -u "${target}" -t "${TEMPLATES_PATH}" -ni -silent -c 100 -rl 500 -H "Cookie: PHPSESSID=746c64jq78gg8944qeom28ldr6; security=low" -json-export "${OUTPUT_FILE}"`;

  console.log("Ejecutando comando principal: ", simpleCommand);

  // EJECUCIÓN ASÍNCRONA
  try {
    list_results = await execPromise(simpleCommand, execOptions); 
  } catch (execError) {
    // Nuclei a menudo arroja códigos de salida distintos a 0 si encuentra vulnerabilidades o errores menores.
    // Solo registramos el error interno si es grave, pero permitimos que el flujo continúe para leer el JSON.
    console.log("Aviso de ejecución de Nuclei:", execError.message);
  }

  // Leer y procesar
  let results = [];
  const existeArchivo = fs.existsSync(OUTPUT_FILE);

  if (existeArchivo) {
    const rawData = fs.readFileSync(OUTPUT_FILE, 'utf8').trim();
    if (rawData) {
      try {
        // -json-export suele generar un array JSON directamente
        const parsed = JSON.parse(rawData);
        results = Array.isArray(parsed) ? parsed : [parsed];
      } catch (e) {
        // Fallback por si Nuclei escribe líneas JSON separadas (JSONL)
        results = rawData.split('\n')
                         .filter(line => line.trim() !== '')
                         .map(line => JSON.parse(line));
      }
    }
  }

  // Prueba de versión opcional (puedes borrar esto cuando el flujo principal sea estable)
  let responseVersion = "";
  try {
    const { stdout, stderr } = await execPromise(`"${NUCLEI_PATH}" -version`, execOptions);
    responseVersion = stdout || stderr; // La versión a veces sale por stderr en las tools de ProjectDiscovery
  } catch (error) {
    responseVersion = error.message;
  }

  return [{
    json: {
      message: results.length > 0 ? "¡Vulnerabilidades detectadas!" : "Escaneo completado (Sin hallazgos)",
      count: results.length,
      nucleiAlerts: results,
      debug: {
        existeArchivo,
        targetUsado: target,
        versionCheck: responseVersion
      },
      list_results
    }
  }];

} catch (error) {
  return [{ json: { error: "Fallo crítico en el nodo: " + error.message } }];
}

// Consolidar todos los hallazgos de las herramientas
const nucleiAlerts = $input.first().json.nucleiAlerts || []; // <-- Cambiado
const activeAlerts = $input.first().json.allAlerts || [];
const sqlmapResults = $input.first().json.sqlmap_results || [];
const ffufResults = $input.first().json.ffufResults || [];

const vulnerabilityMap = new Map();

// Ajustamos la clasificación para soportar el formato lowercase de Nuclei
function classifySeverity(risk) {
  if (!risk) return 'low';
  const riskMap = {
    'High': 'critical',
    'Medium': 'high',
    'Low': 'medium',
    'Informational': 'low',
    'critical': 'critical',
    'high': 'high',
    'medium': 'medium',
    'low': 'low',
    'info': 'low'
  };
  return riskMap[risk] || risk || 'low';
}

function addOrUpdateVulnerability(vuln) {
  const key = `${vuln.type}`;
  if (!vulnerabilityMap.has(key)) {
    vulnerabilityMap.set(key, vuln);
  } else {
    const existing = vulnerabilityMap.get(key);
    if (vuln.source === 'SQLMap' || (vuln.evidence && !existing.evidence)) {
      vulnerabilityMap.set(key, { ...existing, ...vuln });
    }
  }
}

// 1. Procesar alertas Activas de ZAP
activeAlerts.forEach(alert => {
  addOrUpdateVulnerability({
    source: 'OWASP ZAP',
    type: alert.alert,
    severity: classifySeverity(alert.risk),
    url: alert.url,
    description: alert.description || alert.desc,
    solution: alert.solution,
    cweid: alert.cweid,
    evidence: alert.evidence
  });
});

// 2. Procesar alertas de Nuclei
nucleiAlerts.forEach(alert => {
  addOrUpdateVulnerability({
    source: 'Nuclei',
    type: alert.info?.name || 'Vulnerabilidad Detectada',
    severity: classifySeverity(alert.info?.severity),
    url: alert['matched-at'] || alert.host || '',
    description: alert.info?.description || 'Detectado por escáner de plantillas Nuclei.',
    solution: alert.info?.remediation || 'Revisar la configuración y aplicar parches recomendados.',
    // Nuclei agrupa los CWEs en un array, sacamos el número
    cweid: alert.info?.classification?.['cwe-id']?.[0]?.replace('cwe-', '') || null,
    evidence: alert['extracted-results'] ? alert['extracted-results'].join(', ') : (alert.matcher_name || '')
  });
});

// 3. Procesar SQLMap
sqlmapResults.filter(r => r.vulnerable).forEach(result => {
  addOrUpdateVulnerability({
    source: 'SQLMap',
    type: 'SQL Injection',
    severity: 'critical',
    url: result.url,
    description: 'Vulnerabilidad de Inyección SQL detectada mediante pruebas de carga automatizadas.',
    solution: 'Implementar consultas parametrizadas y validación estricta de entradas.',
    cweid: 89,
    evidence: result.details
  });
});

// 4. Procesar ffuf
ffufResults.forEach(result => {
  if (result.status === 403 || result.status === 401) {
    addOrUpdateVulnerability({
      source: 'ffuf',
      type: 'Unauthorized Access Attempt',
      severity: 'low',
      url: result.url,
      description: `Se detectó un recurso protegido con código de estado: ${result.status}`,
      solution: 'Verificar que los controles de acceso y permisos de archivos sean los adecuados.',
      cweid: 284,
      evidence: `HTTP Status: ${result.status}`
    });
  }
});

const allVulnerabilities = Array.from(vulnerabilityMap.values());

const stats = {
  total: allVulnerabilities.length,
  critical: allVulnerabilities.filter(v => v.severity === 'critical').length,
  high: allVulnerabilities.filter(v => v.severity === 'high').length,
  medium: allVulnerabilities.filter(v => v.severity === 'medium').length,
  low: allVulnerabilities.filter(v => v.severity === 'low').length
};

return [{
  json: {
    vulnerabilities: allVulnerabilities,
    statistics: stats,
    scanDate: new Date().toISOString(),
    target: $('Loop Over Items').first().json.target
    }
  }];

// Lista de aplicaciones a escanear
const objetivos = [
  { target: "http://localhost:8081", nombre: "DVWA" }
];

// Mapeamos para que n8n entienda que son "items" separados
return objetivos.map(app => {
  return {
    json: {
      target: app.target,
      nombre: app.nombre,
      zap_api_key: "mppso4aank1578f2lr0kntnoog", // Pasamos la config en cada item
      zap_url: "http://localhost:8090"
    }
  };
});

const axios = require('axios');

const ZAP_API_KEY = $('Loop Over Items').first().json.zap_api_key;
const ZAP_URL = $('Loop Over Items').first().json.zap_url;
const TARGET_URL = $('Loop Over Items').first().json.target;

// Utilizamos la misma sesión válida que ya usas en ffuf y Nuclei
const COOKIE_AUTH = "PHPSESSID=746c64jq78gg8944qeom28ldr6; security=low";

try {
  console.log("Configurando sesión en ZAP...");

  // 1. Inyectar la Cookie globalmente usando el "Replacer" de ZAP
  // Esto obliga a ZAP a enviar la cookie en cada petición del Spider
  await axios.get(`${ZAP_URL}/JSON/replacer/action/addRule/`, {
    params: {
      apikey: ZAP_API_KEY,
      description: 'Sesion_DVWA',
      enabled: 'true',
      matchType: 'REQ_HEADER',
      matchRegex: 'false',
      matchString: 'Cookie',
      replacement: COOKIE_AUTH
    }
  });

  // 2. Iniciar el Spider (Ahora escaneará como usuario autenticado)
  const spiderResponse = await axios.get(`${ZAP_URL}/JSON/spider/action/scan/`, {
    params: {
      apikey: ZAP_API_KEY,
      url: TARGET_URL,
      maxChildren: 100,
      recurse: true
    }
  });

  const scanId = spiderResponse.data.scan;
  console.log(`Iniciando Spider... ID: ${scanId}`);

  // 3. Bucle de espera hasta que el Spider termine
  let progress = 0;
  while (progress < 100) {
    await new Promise(resolve => setTimeout(resolve, 2000));

    const statusResponse = await axios.get(`${ZAP_URL}/JSON/spider/view/status/`, {
      params: { apikey: ZAP_API_KEY, scanId: scanId }
    });

    progress = parseInt(statusResponse.data.status);
    console.log(`Progreso ZAP: ${progress}%`);
  }

  // 4. Extraer los resultados reales
  const urlsResponse = await axios.get(`${ZAP_URL}/JSON/spider/view/results/`, {
    params: { apikey: ZAP_API_KEY, scanId: scanId }
  });

  return [{
    json: {
      message: "Spider completado con sesión activa",
      urlsFound: urlsResponse.data.results,
      count: urlsResponse.data.results.length
    }
  }];

} catch (error) {
  return [{ json: { error: error.message } }];
}

